{e[12057],405302,1,4,280,"「真実は幻想、愛は欲望。\n理想を追い求め、心血を注いで築き上げたこの世界へようこそ。\n読み終えたら、ぜひ感想を教えてくださいね。」",200053,1,"deco/character/xiaoyesiqiyu_0",302002,60,1,"xiaoyesiqiyu_0"},h)g[405303]=b({e[21057],405303,11,130,281,"「ん？　……ふふっ、こんな知る人ぞ知るような場所であなたに会えるなんて、私達、心が通じ合っているのかもしれませんね。それではご褒美に、このお菓子でもあげましょうか。」",200053,2,"deco/character/xiaoyesiqiyu_YY",false,false,false,false,1,false,false,false,false,false,false,"40,-180,1","xiaoyesiqiyu_yy"},h)g[405304]=b({e[17057],405304,2,82,282,"「波の音を聞いてインスピレーションを得ようと思ったのですが、あなたの視線は無視しにくいですね。\n……まあいいでしょう。夏の夜の風が運んできた物語を、一緒に聞きましょうか。」",200053,2,"deco/character/xiaoyesiqiyu_xr",false,false,false,false,false,false,false,"","xiaoyesiqiyu_xr"},h)g[405401]=b({e[46057],405401,false,131,283,false,200054,false,"deco/character/xiamier",302002,60,false,false,false,false,-40,"1",false,false,false,false,false,false,false,"70,340,1","-60,10,1","30,10,1",false,false,false,"-40,0,1",false,false,false,false,1863,812,407,1433,752,1213,2849,1433,752,1213,1024,"xiamier"},h)g[405402]=b({e[23034],405402,1,4,284,"「聴きたい曲はない？ それとも、即興で何か歌おうか。\n君が歩いてくるのを見た瞬間、急にメロディーが降ってきてね。\nきっと、ロマンチックな曲になると思うんだ。」",200054,1,"deco/character/xiamier_0",302002,60,1,false,false,false,false,false,false,false,false,false,"-112,0,1","-97,0,1",1976,870,426,785,812,2329,1964,785,812,2329,1031,false,false,false,false,false,false,false,false,false,false,false,false,"xiamier_0"},h)g[405403]=b({e[21034],405403,13,106,285,"「ここは貸切風呂のはずなんだけど……いや、僕が勘違いしていたのかもしれない。お騒がせしたお詫びに後で何か奢らせて。この温泉のたこ焼きは種類が豊富なことで有名でね。君好みのたこ焼きもあると思うんだ。」",200054,2,"deco/character/xiamier_WQ",false,false,false,false,false,false,false,false,false,false,false,"0,312,1",1835,885,444,835,169,2614,2525,835,606,2614,1261,false,false,false,false,false,false,false,false,false,false,false,false,"xiamier_wq"},h)g[405404]=b({e[46057],405404,12,132,286,"「はは……今まで何度も盛大な祝祭に参加してきたけど、今日のこのプライベートな場ほど緊張したことはないよ。僕の心の音楽、聴いてくれるかい？」",200054,2,"deco/character/xiamier_LF",false,false,1,false,false,false,false,"1",false,false,"-420,0,1","150,0,0.98","-420,0,1","-42